name: Publish Extension to Marketplace
on:
  push:
    branches:
      - main
    paths:
      - '.github/workflows/extension-publish-marketplace.yml'
      - 'package.json'
      - 'package-lock.json'
      - 'dist/**'
      - '!**.md'
      - '!**.txt'
      - '!**.log'
      - '!**.yml'
      - '!**.yaml'
  workflow_dispatch:

jobs:
  publish-extension:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Repository
        uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'
          registry-url: 'https://registry.npmjs.org'

      - name: Install Dependencies
        uses: bahmutov/npm-install@v1
        with:
          working-directory: .

      - name: Build Extension
        run: |
          npm run build

      - name: Publish to Visual Studio Marketplace
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const path = require('path');

            // Check if vsix file exists
            const vsixPath = path.join(process.env.GITHUB_WORKSPACE, 'dist', '*.vsix');
            const files = fs.readdirSync('dist');
            const vsixFile = files.find(file => file.endsWith('.vsix'));

            if (!vsixFile) {
              throw new Error('No .vsix file found in dist directory');
            }

            console.log(`Found vsix file: ${vsixFile}`);

            // For demonstration purposes, we'll just log that publishing would happen
            // In practice, you'd use the official VS Code Marketplace publisher
            console.log('VSIX file ready for publishing to Marketplace');

      - name: Publish to Open VSX Registry
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const path = require('path');

            // Check if vsix file exists
            const vsixPath = path.join(process.env.GITHUB_WORKSPACE, 'dist', '*.vsix');
            const files = fs.readdirSync('dist');
            const vsixFile = files.find(file => file.endsWith('.vsix'));

            if (!vsixFile) {
              throw new Error('No .vsix file found in dist directory');
            }

            console.log(`Found vsix file: ${vsixFile}`);

            // For demonstration purposes, we'll just log that publishing would happen
            // In practice, you'd use the official Open VSX publisher
            console.log('VSIX file ready for publishing to Open VSX Registry')
